CREATE OR REPLACE FUNCTION public.nmis_send_complaint_message(p_complaint_id uuid, p_sender_type text, p_sender_name text, p_sender_email text, p_message text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog AS $$ DECLARE v_message_id uuid; BEGIN INSERT INTO public.complaint_messages (complaint_id, sender_type, sender_name, sender_email, message) VALUES (p_complaint_id, p_sender_type, p_sender_name, p_sender_email, p_message) RETURNING id INTO v_message_id; RETURN v_message_id; END; $$; CREATE OR REPLACE FUNCTION public.nmis_get_complaint_messages(p_complaint_id uuid) RETURNS TABLE (id uuid, complaint_id uuid, sender_type text, sender_name text, sender_email text, message text, created_at timestamptz) LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public, pg_catalog AS $$ SELECT id, complaint_id, sender_type, sender_name, sender_email, message, created_at FROM public.complaint_messages WHERE complaint_id = p_complaint_id ORDER BY created_at ASC; $$; REVOKE ALL ON FUNCTION public.nmis_send_complaint_message(uuid, text, text, text, text) FROM PUBLIC; REVOKE ALL ON FUNCTION public.nmis_get_complaint_messages(uuid) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.nmis_send_complaint_message(uuid, text, text, text, text) TO anon, authenticated; GRANT EXECUTE ON FUNCTION public.nmis_get_complaint_messages(uuid) TO anon, authenticated;